```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The contract guarantees len(text) <= 100000, so the text is
        // forwarded as-is. The host channel stamps its own session identity on
        // the confirmation. This node never makes up that identity.
        let confirmation = response_channel::send(&reply.text);

        // The postconditions say the output must report a real delivery with a
        // present session. If the channel did not confirm, the node must not
        // invent a confirmation. It traps instead, so no output is produced.
        if !confirmation.delivered {
            panic!("response channel did not confirm delivery");
        }
        if confirmation.session.is_empty() {
            panic!("response channel returned no session identity");
        }

        confirmation
    }
}

export!(Node);
